App.Http.EmailTemplateSettings={save:function(t){const e=App.Utils.Url.siteUrl("email_template_settings/save"),s={csrf_token:vars("csrf_token"),templates:t};return $.post(e,s)},preview:function(t,e){const s=App.Utils.Url.siteUrl("email_template_settings/preview"),p={csrf_token:vars("csrf_token"),template_key:t,html:e};return $.post(s,p)}};